import json
src=[[3,3,3,2,3,2,3],[3,3,3,2,3,3,3],[3,2,3,3,3,2,2],[3,3,2,2,3,3,3],[3,3,3,3,3,3,3],[3,3,3,3,3,3,3]]
g=[]
for _ in range(2):
    for row in src:
        g.append(row+[8]+row+[8]+row)
    if len(g)==6:
        g.append([8]*23)
assert len(g)==13 and all(len(row)==23 for row in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

import json
seed=[[3,3,3,2,3,2,3],[3,3,3,2,3,3,3],[3,2,3,3,3,2,2],[3,3,2,2,3,3,3],[3,3,3,3,3,3,3],[3,3,3,3,3,3,3]]
out=[]
for i in range(13):
 if i==6: out.append([8]*23)
 else:
  row=seed[i if i<6 else i-7]
  out.append(row+[8]+row+[8]+row)
assert len(out)==13 and all(len(r)==23 for r in out)
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

